/** Actual Jett and complete actual Basic/evolved Mega Pokemon, preserving printed identity and Supporter limits. */
public final class GeneratedRuleBatch69Test {
    static final UUID A=FamilyDrawCountTest.A,B=FamilyDrawCountTest.B;
    static final String JETT="me5_en_079",LATIAS="me1_en_100",RIOLU="me1_en_076",LUCARIO="me1_en_077";
    static final CardDatabase DB=BundledRules.loadCardDefinitions();static final CombatCatalog COMBAT=BundledCombatData.load();
    static void check(boolean b,String s){FamilyDrawCountTest.check(b,s);}
    static CardInstance hand(ServerMatch m,UUID owner,String id){return FamilyDrawCountTest.hand(m,owner,id);}
    static FamilyDrawCountTest.Config config(){var c=new FamilyDrawCountTest.Config();c.trainerId=JETT;c.definition=DB.find(JETT).orElseThrow();c.trainer=COMBAT.trainer(JETT).orElseThrow();return c;}
    public static void main(String[] args){printed();nativeCounts();nativePokemon();authority();System.out.println("GeneratedRuleBatch69Test passed: actual Jett definition/program,0..6 opposing Mega counts, no-target/first-turn/quota rejection, actual Mega Latias and evolved Mega Lucario with own Mega excluded, short-deck draw and server authority/replay");}
    static void printed(){var c=config();check(c.definition.effectSupport()==EffectSupport.SUPPORTED&&c.definition.trainerCategory()==TrainerCategory.SUPPORTER&&c.definition.regulationMark().equals("J")&&c.definition.copyLimit()==4&&!c.trainer.endsTurn(),"Jett metadata or turn behavior changed");var p=c.trainer.effectProgram().triggers();check(p.size()==1&&p.getFirst().trigger()==EffectTrigger.ON_CARD_PLAYED&&p.getFirst().effects().size()==1,"Jett program wrong trigger");var e=p.getFirst().effects().getFirst();var d=DrawCount.from(e);check(d.amount()==1&&d.countType()==ConditionType.POKEMON_COUNT&&d.countTarget()==EffectTarget.ALL_OPPONENT_POKEMON&&d.countArguments().get("pokemon_families").equals("MEGA_EVOLUTION_EX"),"Jett counted wrong field/family");
        for(String id:List.of(LATIAS,LUCARIO)){var card=DB.find(id).orElseThrow();check(card.pokemonFamilies().containsAll(Set.of(PokemonFamily.RULE_BOX,PokemonFamily.EX,PokemonFamily.MEGA_EVOLUTION_EX))&&COMBAT.pokemon(id).orElseThrow().prizeCards()==3,"Actual modern Mega lost ex/prize identity");}
        check(DB.all().stream().filter(x->x.pokemonFamilies().contains(PokemonFamily.MEGA_EVOLUTION_EX)).count()==133,"Explicit printed Mega marker scope changed");check(DB.all().stream().filter(x->x.pokemonFamilies().contains(PokemonFamily.EX_LEGACY)).noneMatch(x->x.pokemonFamilies().contains(PokemonFamily.MEGA_EVOLUTION_EX)),"Old uppercase EX acquired modern Mega marker");}
    static void nativeCounts(){for(int n=0;n<=6;n++){var c=config();c.activeId=n==6?"mega":"plain";c.benches=Collections.nCopies(n==6?5:n,"mega");var m=FamilyDrawCountTest.game(c);int size=m.privateView(A).hand().size();if(n==0){FamilyDrawCountTest.atomic(m,()->FamilyDrawCountTest.play(m,JETT));continue;}FamilyDrawCountTest.play(m,JETT);check(m.privateView(A).hand().size()==size-1+n,"Actual Jett draw amount wrong "+n);FamilyDrawCountTest.atomic(m,()->FamilyDrawCountTest.play(m,JETT));}}
    static ServerMatch nativeGame(){var defs=new ArrayList<CardDefinition>();for(String id:List.of(JETT,LATIAS,RIOLU,LUCARIO))defs.add(DB.find(id).orElseThrow());defs.add(new CardDefinition("filler","填充能量",CardCategory.ENERGY,TrainerCategory.NONE,"J",Set.of("international"),false,true,60,Map.of(),EffectSupport.SUPPORTED,null));var profiles=new HashMap<String,PokemonProfile>();for(String id:List.of(LATIAS,RIOLU,LUCARIO))profiles.put(id,COMBAT.pokemon(id).orElseThrow());var catalog=new CombatCatalog(profiles,Map.of("filler",EnergyType.COLORLESS),Map.of(JETT,COMBAT.trainer(JETT).orElseThrow()));var decks=new ArrayList<List<CardInstance>>();
        for(UUID owner:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++){String id=owner.equals(A)?(i<4?JETT:i<24?LATIAS:"filler"):(i<16?LATIAS:i<32?RIOLU:i<44?LUCARIO:"filler");cards.add(new CardInstance(new UUID(owner.getLeastSignificantBits(),i+1),owner,id));}decks.add(cards);}
        for(int seed=0;seed<1000;seed++){var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),catalog,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(m.privateView(A).hand().stream().filter(x->x.definitionId().equals(LATIAS)).count()<2||m.privateView(B).hand().stream().noneMatch(x->x.definitionId().equals(LATIAS))||m.privateView(B).hand().stream().noneMatch(x->x.definitionId().equals(RIOLU)))continue;
            m.chooseOpeningActive(A,hand(m,A,LATIAS).instanceId());m.placeOpeningBench(A,hand(m,A,LATIAS).instanceId());m.chooseOpeningActive(B,hand(m,B,LATIAS).instanceId());m.placeOpeningBench(B,hand(m,B,RIOLU).instanceId());m.startAfterOpening(A);m.startAfterOpening(B);OpeningTestSupport.complete(m,A,B,0);m.drawCardsByEffect(A,A,28);m.drawCardsByEffect(A,B,28);if(m.privateView(A).hand().stream().noneMatch(x->x.definitionId().equals(JETT))||m.privateView(B).hand().stream().noneMatch(x->x.definitionId().equals(LUCARIO)))continue;
            m.endTurn(A);m.evolveByEffect(B,m.benchPokemonView(B).getFirst().pokemonId(),hand(m,B,LUCARIO).instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);m.endTurn(B);return m;
        }throw new AssertionError("No native Jett/Mega fixture");}
    static void nativePokemon(){for(boolean shortDeck:List.of(false,true)){var m=nativeGame();if(shortDeck)m.discardTopDeckCardsByEffect(A,A,m.privateView(A).deck().size()-1);int size=m.privateView(A).hand().size();var opponent=m.privateView(B);FamilyDrawCountTest.play(m,JETT);check(m.privateView(A).hand().size()==size+(shortDeck?0:1)&&m.privateView(B).equals(opponent)&&m.phase()==MatchPhase.TURN,"Actual Basic/evolved Mega count or short-deck boundary wrong");}}
    static void authority(){var c=config();c.activeId="mega";c.later=false;var first=FamilyDrawCountTest.game(c);FamilyDrawCountTest.atomic(first,()->FamilyDrawCountTest.play(first,JETT));var m=FamilyDrawCountTest.game(config());var card=hand(m,A,JETT);FamilyDrawCountTest.atomic(m,()->m.playTrainer(B,card.instanceId(),null));var session=MatchSession.multiplayer(m,A,B);var view=session.view(A,A);var option=view.options().stream().filter(o->o.labelZh().contains("捷朵")).findFirst().orElseThrow();session.submit(A,A,view.revision(),option.index());FamilyDrawCountTest.atomic(m,()->session.submit(A,A,view.revision(),option.index()));FamilyDrawCountTest.atomic(m,()->FamilyDrawCountTest.play(m,JETT));}
}
